// Validates the HTTP request body against the OrderCreated v1 input contract.
// Output 1: valid -> msg.event is the full event to publish.
// Output 2: invalid -> HTTP 400 response, nothing is published.
const orderEvent = global.get('orderEvent');
const input = msg.payload;
const headerCid = msg.req && msg.req.headers ? msg.req.headers['x-correlation-id'] : undefined;
const correlationId = headerCid || (input && typeof input === 'object' ? input.correlationId : undefined);

const errors = (input && typeof input === 'object')
    ? orderEvent.validateInput(input)
    : ['body must be a JSON object'];

if (errors.length > 0) {
    node.warn(JSON.stringify({ result: 'REJECTED', correlationId: correlationId || null, errors }));
    msg.statusCode = 400;
    msg.payload = {
        status: 'REJECTED',
        error: 'VALIDATION_FAILED',
        details: errors,
        correlationId: correlationId || null
    };
    return [null, msg];
}

msg.event = orderEvent.buildEvent(input, correlationId);
return [msg, null];

// Lazily create one long-lived Kafka producer for this node on the first request.
// Registered here (not in On Start) because only the main sandbox exposes node.on,
// and a 'close' listener with a done callback is awaited by Node-RED on redeploy/shutdown.
if (!context.get('producer')) {
    const { Kafka, Partitioners, logLevel } = global.get('kafkajs');
    const retries = Number(env.get('PRODUCER_RETRIES') || 2);
    const kafka = new Kafka({
        clientId: 'nodered-order-producer',
        brokers: (env.get('KAFKA_BROKERS') || 'kafka:19092').split(','),
        connectionTimeout: 1000,
        requestTimeout: 3000,
        retry: { retries, initialRetryTime: 300, maxRetryTime: 1000, factor: 0.2, multiplier: 2 },
        logLevel: logLevel.NOTHING
    });
    const producer = kafka.producer({ allowAutoTopicCreation: false, createPartitioner: Partitioners.DefaultPartitioner });
    context.set('producer', producer);
    context.set('retries', retries);
    context.set('connected', false);
    node.status({ fill: 'grey', shape: 'ring', text: 'idle' });

    node.on('close', function (removed, done) {
        producer.disconnect().catch(() => {}).then(() => done());
    });
}

// Publishes msg.event to the orders topic, keyed by orderId.
// Output 1: broker acknowledged (acks=all) -> HTTP 202.
// Output 2: broker unavailable after the configured retries -> HTTP 503.
const producer = context.get('producer');
const retries = context.get('retries');
const topic = env.get('ORDERS_TOPIC') || 'qa.orders.v1';
const event = msg.event;
const started = Date.now();

(async () => {
    try {
        if (!context.get('connected')) {
            await producer.connect();
            context.set('connected', true);
        }
        const [meta] = await producer.send({
            topic,
            acks: -1,
            timeout: 3000,
            messages: [{
                key: event.orderId,
                value: JSON.stringify(event),
                headers: {
                    'correlation-id': event.correlationId,
                    'event-type': event.eventType,
                    'schema-version': String(event.schemaVersion)
                }
            }]
        });
        node.status({ fill: 'green', shape: 'dot', text: 'published ' + event.orderId + ' @' + meta.baseOffset });
        msg.statusCode = 202;
        msg.payload = {
            status: 'PUBLISHED',
            topic,
            partition: meta.partition,
            offset: meta.baseOffset,
            key: event.orderId,
            eventId: event.eventId,
            correlationId: event.correlationId
        };
        node.send([msg, null]);
    } catch (err) {
        context.set('connected', false);
        const elapsedMs = Date.now() - started;
        node.status({ fill: 'red', shape: 'ring', text: 'broker unavailable' });
        node.warn(JSON.stringify({ result: 'PUBLISH_FAILED', correlationId: event.correlationId, error: err.message, elapsedMs }));
        msg.statusCode = 503;
        msg.payload = {
            status: 'FAILED',
            error: 'BROKER_UNAVAILABLE',
            message: err.message,
            retries,
            elapsedMs,
            correlationId: event.correlationId
        };
        node.send([null, msg]);
    }
    node.done();
})();
return;

// Started once by the 'start consumer' inject node; later triggers are ignored.
if (context.get('consumer')) { return null; }

// Long-lived Kafka consumer. For each record on the orders topic:
//  - valid OrderCreated  -> OrderProcessed result published to the processed topic (output 1)
//  - malformed / invalid -> OrderRejected record published to the DLQ topic (output 2)
// The offset is committed only after the result/DLQ write succeeds (autoCommitThreshold: 1),
// so a restart with the same group ID resumes after the last fully handled record.
const { Kafka, Partitioners, logLevel } = global.get('kafkajs');
const orderEvent = global.get('orderEvent');
const brokers = (env.get('KAFKA_BROKERS') || 'kafka:19092').split(',');
const inTopic = env.get('ORDERS_TOPIC') || 'qa.orders.v1';
const outTopic = env.get('PROCESSED_TOPIC') || 'qa.orders.processed.v1';
const dlqTopic = env.get('DLQ_TOPIC') || 'qa.orders.dlq.v1';
const groupId = env.get('CONSUMER_GROUP_ID') || 'nodered-order-processor';

const kafka = new Kafka({ clientId: 'nodered-order-consumer', brokers, logLevel: logLevel.WARN });
const consumer = kafka.consumer({ groupId, sessionTimeout: 10000, heartbeatInterval: 1000, maxWaitTimeInMs: 1000 });
const producer = kafka.producer({ allowAutoTopicCreation: false, createPartitioner: Partitioners.DefaultPartitioner });
context.set('consumer', consumer);
context.set('producer', producer);

const header = (message, name) => message.headers && message.headers[name] ? message.headers[name].toString() : null;

async function handle({ topic, partition, message }) {
    const source = { topic, partition, offset: message.offset };
    const raw = message.value ? message.value.toString('utf8') : '';
    let event;
    let reason = null;
    let errors = [];
    try {
        event = JSON.parse(raw);
    } catch (e) {
        reason = 'INVALID_JSON';
        errors = [e.message];
    }
    if (!reason) {
        errors = orderEvent.validateEvent(event);
        if (errors.length > 0) reason = 'SCHEMA_VALIDATION_FAILED';
    }

    if (!reason) {
        const result = orderEvent.buildProcessedResult(event, source);
        await producer.send({
            topic: outTopic,
            acks: -1,
            messages: [{
                key: event.orderId,
                value: JSON.stringify(result),
                headers: { 'correlation-id': event.correlationId, 'event-type': result.eventType }
            }]
        });
        node.status({ fill: 'green', shape: 'dot', text: 'processed ' + event.orderId + ' @' + message.offset });
        node.send([{ topic: outTopic, payload: result }, null]);
        return;
    }

    const correlationId = header(message, 'correlation-id')
        || (event && typeof event === 'object' && typeof event.correlationId === 'string' ? event.correlationId : null);
    const rejection = {
        schemaVersion: 1,
        eventType: 'OrderRejected',
        reason,
        errors,
        correlationId,
        source,
        rawValue: raw.slice(0, 10000),
        rejectedAt: new Date().toISOString()
    };
    await producer.send({
        topic: dlqTopic,
        acks: -1,
        messages: [{
            key: message.key,
            value: JSON.stringify(rejection),
            headers: correlationId ? { 'correlation-id': correlationId, 'event-type': 'OrderRejected' } : { 'event-type': 'OrderRejected' }
        }]
    });
    node.status({ fill: 'yellow', shape: 'ring', text: 'rejected @' + message.offset + ' (' + reason + ')' });
    node.warn(JSON.stringify({ result: 'REJECTED', reason, errors, source, correlationId }));
    node.send([null, { topic: dlqTopic, payload: rejection }]);
}

// Leave the group cleanly on redeploy/shutdown so a restarted consumer with the same
// group ID gets the partition immediately (no wait for the session timeout).
// A 'close' listener with a done callback is awaited by Node-RED (On Stop is not), and
// node.on is only available in the main sandbox, which is why startup happens here.
node.on('close', function (removed, done) {
    consumer.disconnect().catch(() => {})
        .then(() => producer.disconnect()).catch(() => {})
        .then(() => done());
});

(async () => {
    node.status({ fill: 'grey', shape: 'ring', text: 'connecting' });
    await producer.connect();
    await consumer.connect();
    await consumer.subscribe({ topics: [inTopic], fromBeginning: true });
    consumer.on(consumer.events.GROUP_JOIN, () => node.status({ fill: 'blue', shape: 'dot', text: 'joined ' + groupId }));
    await consumer.run({ autoCommit: true, autoCommitThreshold: 1, eachMessage: handle });
})().catch((err) => {
    node.status({ fill: 'red', shape: 'ring', text: 'start failed' });
    node.error('Kafka consumer failed to start: ' + err.message);
});
return null;
